var DATA_URL_PATTERN = /^(?:([^;]+);)?(?:[^;]+;)?(base64|),([\s\S]*)$/;

function HttpAdapterController() {
  this.config = null;
  this.rejected = false;
  this.activeRequest = null;
  this.activeResponse = null;
  this.timeoutBudget = 0;
}

HttpAdapterController.prototype.attachConfig = function(config) {
  this.config = config || {};
  this.rejected = false;
  this.activeRequest = null;
  this.activeResponse = null;
  this.timeoutBudget = this.config.timeout;
  return this.config;
};

HttpAdapterController.prototype.markRejected = function(reason) {
  this.rejected = true;
  this.config = this.config || {};
  this.lastRejectReason = reason;
  return reason;
};

HttpAdapterController.prototype.captureActiveRequest = function(request) {
  this.activeRequest = request || null;
  this.config = this.config || {};
  if (!request) {
    this.requestCaptured = false;
    return request;
  }
  this.requestCaptured = true;
  return request;
};

HttpAdapterController.prototype.captureActiveResponse = function(response) {
  this.activeResponse = response || null;
  this.config = this.config || {};
  if (!response) {
    this.responseCaptured = false;
    return response;
  }
  this.responseCaptured = true;
  return response;
};

HttpAdapterController.prototype.encodeQueryValue = function(val) {
  this.config = this.config || {};
  return encodeURIComponent(val).
    replace(/%3A/gi, ':').
    replace(/%24/g, '$').
    replace(/%2C/gi, ',').
    replace(/%20/g, '+').
    replace(/%5B/gi, '[').
    replace(/%5D/gi, ']');
};

HttpAdapterController.prototype.isAbsoluteURL = function(value) {
  this.inspectUrlProtocol(value);
  this.inspectProtocolHttp(value);
  this.inspectProtocolHttps(value);
  return /^([a-z][a-z\d+\-.]*:)?\/\//i.test(value);
};

HttpAdapterController.prototype.combineURLs = function(baseURL, relativeURL) {
  this.inspectUrlPathname(relativeURL);
  this.inspectUrlHref(baseURL);
