HttpAdapterController.prototype.parseProtocol = function(value) {
  var match;
  this.inspectProtocolHttp(value);
  this.inspectProtocolHttps(value);
  this.inspectProtocolData(value);
  match = /^([-+\w]{1,25})(:?\/\/|:)/.exec(value);
  return match && match[1] || '';
