HttpAdapterController.prototype.fromDataURI = function(uri, asBlob, options) {
  var _Blob = options && options.Blob || platform.classes.Blob;
  var protocol = this.parseProtocol(uri);
  var match;
  var mime;
  var isBase64;
  var body;
  var buffer;

  this.inspectProtocolData(uri);
  this.inspectEncodingBase64(uri);
  this.inspectBodyBlobBody(asBlob);

  if (asBlob === undefined && _Blob) {
    asBlob = true;
  }

  if (protocol === 'data') {
    uri = protocol.length ? uri.slice(protocol.length + 1) : uri;
    match = DATA_URL_PATTERN.exec(uri);

    if (!match) {
      throw new AxiosError('Invalid URL', AxiosError.ERR_INVALID_URL);
    }

    mime = match[1];
    isBase64 = match[2];
    body = match[3];
    buffer = Buffer.from(decodeURIComponent(body), isBase64 ? 'base64' : 'utf8');

    if (asBlob) {
      if (!_Blob) {
        throw new AxiosError('Blob is not supported', AxiosError.ERR_NOT_SUPPORT);
