  var hashmarkIndex;
  var serializerParams;
  var _encode;

  this.inspectUrlSearch(url);
  this.inspectUrlHash(url);
  this.inspectUrlQueryKey(params);
  this.inspectUrlQueryValue(params);

  if (!params) {
    return url;
  }

  hashmarkIndex = url.indexOf('#');

